return $input.all().map((item) => {
  const o = item.json || {};
  const now = new Date().toISOString();
  const score = Number(o.impact_score || 75);
  const provider = o.provider_name || o.provider_key || 'Transit';
  const mode = String(o.mode || 'TRANSIT').toUpperCase();
  const place = [o.asset_name, o.route_name, o.municipality, o.state].filter(Boolean).join(' · ');
  const message = [o.description, o.route_name, o.asset_name].filter(Boolean).join(' · ') || 'High-impact transit condition detected.';
  const alert = {
    schema_version: '1.0',
    alert_id: `TRANSIT_INTEL:${o.provider_key || 'TRANSIT'}:${o.external_key || o.transit_observation_id}`,
    source: 'TRANSIT_INTELLIGENCE',
    source_event_id: o.external_key || o.transit_observation_id,
    category: 'TRANSIT',
    subtype: `${String(o.provider_key || 'TRANSIT').toUpperCase()}_${mode}`.replace(/[^A-Z0-9]+/g, '_'),
    status: o.status || 'ACTIVE',
    event_action: o.alert_emitted_at ? 'UPDATE' : 'NEW',
    title: o.title || `${provider} transit impact`,
    message,
    priority: score >= 90 ? 5 : 4,
    county: o.county || '',
    municipality: o.municipality || '',
    location: {
      label: place,
      address: '',
      state: o.state || '',
      zip: '',
      latitude: o.latitude || null,
      longitude: o.longitude || null,
      block: '',
      lot: '',
      qualifier: '',
      parcel_id: ''
    },
    tags: ['transit-intelligence', String(o.provider_key || 'transit').toLowerCase(), mode.toLowerCase(), 'high-impact'],
    click_url: o.source_url || '',
    source_url: o.source_url || '',
    observed_at: o.last_changed_at || now,
    source_updated_at: o.last_changed_at || null,
    received_at: now,
    expires_at: o.ends_at || null,
    metadata: {
      transit_observation_id: o.transit_observation_id,
      provider_key: o.provider_key || '',
      provider_name: provider,
      impact_score: score,
      route_key: o.route_key || '',
      route_name: o.route_name || '',
      asset_key: o.asset_key || '',
      asset_name: o.asset_name || '',
      starts_at: o.starts_at || null,
      ends_at: o.ends_at || null
    }
  };
  alert.search_text = [
    alert.source, alert.category, alert.subtype, alert.title, alert.message,
    provider, mode, o.route_key, o.route_name, o.asset_key, o.asset_name,
    o.municipality, o.county, o.state, ...alert.tags
  ].filter(Boolean).join(' ');
  return { json: alert };
});
